/**
 * Tài liệu missbacxiu: tab 1 ("Ý tưởng phổ biến") of missbacxiu's doc "[missbac.xiu V4] chống bí ý task 2",
 * digitized with her permission. Macro A (nguyên nhân), B (tác động), C (giải pháp), each split into parts
 * (Nội dung, Giải đề, …) that hold text lines and tables.
 *
 * tab1.json is generated by scripts/missbacxiu-build.py from a dump of the doc; edit the JSON by hand for small
 * fixes. Prompts sit inside the "Đề áp dụng" / "Đề luyện tư duy" cells as `prompts`, with her hint and exam date.
 */
import data from './tab1.json';

/** One line of her text. `li` is the list depth when the line is a bullet; `h` marks a heading line. */
export interface DocLine {
  t: string;
  li?: number;
  h?: boolean | string;
  href?: string;
  /** She marked it "super important". */
  key?: boolean;
}

export interface DocPrompt {
  /** Stable id from the prompt's words ("mbx-…"), the same wherever the prompt is listed. */
  id: string;
  text: string;
  /** Her note on how to use the idea for this prompt (Vietnamese). */
  hint?: string;
  /** Exam date when she marked it as a real test, e.g. "6.7.2026" or "T8.2026". */
  date?: string;
  /** The label line the prompt is listed under in its cell, e.g. "Ý tưởng về cha mẹ bận". */
  label?: string;
}

/**
 * A table cell. `span: 'up'` / `'left'` marks a slot covered by a merged cell above / to the left;
 * `rs` / `cs` are the merged cell's spans. `blank` cells are the ones she left for students to fill.
 */
export interface DocCell {
  lines?: DocLine[];
  prompts?: DocPrompt[];
  rs?: number;
  cs?: number;
  span?: 'up' | 'left';
  blank?: boolean;
}

export interface DocTable {
  kind: 'table';
  id: string;
  head: string[];
  rows: DocCell[][];
}

export type DocBlock = ({ kind: 'text' } & DocLine) | DocTable;

export interface DocPart {
  id: string;
  title: string | null;
  note?: string;
  blocks: DocBlock[];
}

export interface DocMacro {
  id: 'A' | 'B' | 'C';
  name: string;
  title: string;
  parts: DocPart[];
}

export const MBX_SOURCE: string = data.source;
export const MBX_MACROS = data.macros as DocMacro[];

export interface IndexedPrompt extends DocPrompt {
  macro: DocMacro['id'];
  /** The part it sits in (for "Xem trong tài liệu"), its table and row. */
  part: string;
  table: string;
  row: number;
  /** Her idea for this row: the first line of its first column, e.g. "2. Đặc điểm của xã hội hiện đại (modern society)". */
  idea: string;
}

const ideaCell = (rows: DocCell[][], ri: number): DocCell | undefined => {
  // A merged first cell sits on the first row it covers.
  for (let r = ri; r >= 0; r--) if (!rows[r][0]?.span) return rows[r][0];
  return undefined;
};

let INDEX: IndexedPrompt[] | null = null;

/** Every prompt in the doc, first occurrence only (several appear under more than one idea). */
export function mbxPrompts(): IndexedPrompt[] {
  if (INDEX) return INDEX;
  const seen = new Set<string>();
  const out: IndexedPrompt[] = [];
  for (const m of MBX_MACROS) {
    for (const p of m.parts) {
      for (const b of p.blocks) {
        if (b.kind !== 'table') continue;
        b.rows.forEach((row, ri) => {
          for (const c of row) {
            for (const pr of c.prompts ?? []) {
              if (seen.has(pr.id)) continue;
              seen.add(pr.id);
              const idea = ideaCell(b.rows, ri)?.lines?.[0]?.t ?? '';
              out.push({ ...pr, macro: m.id, part: p.id, table: b.id, row: ri, idea });
            }
          }
        });
      }
    }
  }
  return (INDEX = out);
}

export const findMbxPrompt = (id: string): IndexedPrompt | null => mbxPrompts().find((p) => p.id === id) ?? null;

/** Her notes for the row a prompt sits in (every cell but the prompts), as plain text for the AI, cut to `max` characters. */
export function mbxRowText(p: IndexedPrompt, max = 3000): string {
  const t = MBX_MACROS.flatMap((m) => m.parts).flatMap((pt) => pt.blocks).find((b): b is DocTable => b.kind === 'table' && b.id === p.table);
  if (!t) return '';
  const row = t.rows[p.row];
  const cells = row.map((c, ci) => (c.span === 'up' && ci === 0 ? ideaCell(t.rows, p.row) : c));
  const out = cells.flatMap((c, ci) => (c && !c.span || ci === 0) && c?.lines?.length ? [t.head[ci] + ':\n' + c.lines.map((l) => '- ' + l.t).join('\n')] : []).join('\n\n');
  return out.length > max ? out.slice(0, max) + '…' : out;
}
